interface Parser {}
class JsonParser implements Parser {}
class XmlParser implements Parser {}
class ParserFactory {
    static Parser create(String type) {
        return switch (type) {
            case "json" -> new JsonParser();
            case "xml" -> new XmlParser();
            default -> throw new IllegalArgumentException(type);
        };
    }
}

